import { SeedTsOauthTokenOptionalClient } from "@fern/ts-oauth-token-optional";

const client = new SeedTsOauthTokenOptionalClient({ baseUrl: "YOUR_BASE_URL", clientId: "YOUR_CLIENT_ID", clientSecret: "YOUR_CLIENT_SECRET" });
